INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(3926, 'plPL', '%s aktywuje się!', '', 0),
(3927, 'plPL', 'Sekwencja samozniszczenia aktywowana.', '', 0),
(3949, 'plPL', 'Środki zapobiegające ucieczce aktywowane. Samozniszczenie za 20 sekund....', '', 0),
(3950, 'plPL', 'Jednostka Alarmobomba 2600 uległa awarii. Obejście samozniszczenia [AKTYWNE]. Odnowienie [AKTYWNE].', '', 0),
(3992, 'plPL', 'Bzzzzzt!$B$BWitaj w matrycowym perforografie 3005 łamane na B, terminalu o poziomie zabezpieczeń beta.$B$BAby uzyskać dostęp do funkcji terminalu, musisz posiadać żółtą kartę perforowaną.\n01000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001', '', 0),
(3994, 'plPL', 'Bzzzzzt!$B$BWitaj w matrycowym perforografie 3005 łamane na C, terminalu o poziomie zabezpieczeń chi.$B$BAby uzyskać dostęp do funkcji terminalu, musisz posiadać niebieską kartę perforowaną.\n01010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000', '', 0),
(4002, 'plPL', 'Bzzzzzt!$B$BWitaj w matrycowym perforografie 3005 łamane na D, terminalu o poziomie zabezpieczeń delta.$B$BAby uzyskać dostęp do funkcji terminalu, musisz posiadać czerwoną kartę perforowaną.\n01010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100', '', 0),
(4003, 'plPL', 'Pobierz kartę danych wysokiego poziomu.', 'Pobierz kartę danych wysokiego poziomu.', 0),
(4009, 'plPL', 'Technologiczny heurystometr matrycowego perforografu wykrył twoje uzdolnienia inżynieryjne. Możesz teraz wybrać spośród następujących opcji:\n01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001', '', 0),
(4011, 'plPL', 'Uzyskiwanie dostępu...\nPustka -- inżynier <#skill_level == n3wb>\n \n01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010\nODMOWA DOSTĘPU!', '', 0),
(4012, 'plPL', 'Przyznano dostęp do danych. Miłego dnia!\n01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011', '', 0),
(4050, 'plPL', '', 'Z twoją pomocą zdołam zbadać te tunele.', 0),
(4051, 'plPL', '', 'Sprawdźmy, skąd biorą się te troggi... i położmy kres tej inwazji!', 0),
(4052, 'plPL', '', 'Co za zniszczenia... co za okropny bałagan...', 0),
(4083, 'plPL', '', 'Dzięki Światłości, że jesteś! W tej chwili przyjęłabym pomoc nawet od dwugłowego ogra.\nMiasto opanowały troggi! Próby ich wytępienia skończyły się masowym skażeniem. Ale wciąż jest nadzieja.\nNasi naukowcy, którzy ewakuowali się do Żelaznej Kuźni, pracują nad lekarstwem na chorobę popromienną. Tymczasem jeśli pomożesz mi powstrzymać inwazję troggów, może uda się odbić miasto. ', 0),
(4084, 'plPL', 'Jestem $ggotów:gotowa; zacząć.', 'Jestem $ggotów:gotowa; zacząć.', 0),
(4129, 'plPL', '', 'Cicho tu....', 0),
(4130, 'plPL', '', '...zbyt cicho.', 0),
(4131, 'plPL', '', 'Patrz! Tam, przy ścianie tunelu!', 0),
(4132, 'plPL', '', 'Wtargnięcie troggów! Osłaniaj mnie, a ja zasypię wybuchem ten otwór!', 0),
(4133, 'plPL', '', 'Chyba jeden ładunek nie wystarczy. Nie dopuszczaj ich do mnie!', 0),
(4134, 'plPL', '', 'Ładunki założone. Cofnij się, zanim wybuchną!', 0),
(4135, 'plPL', '', 'Wybuch za 10 sekund!', 0),
(4136, 'plPL', '', 'Wybuch za 5 sekund. Opuść tunel! Trzymaj się z daleka!', 0),
(4137, 'plPL', '', 'UWAGA, ODPALAM!', 0),
(4142, 'plPL', 'Uwaga! Uwaga! Intruz! Intruz!', '', 0),
(4171, 'plPL', 'Bzzzzzt!$B$BWitaj w matrycowym perforografie 3005 łamane na B, terminalu o poziomie zabezpieczeń beta.$B$BWykryto żółtą kartę perforowaną. Dostęp przyznany.\n01001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001', '', 0),
(4172, 'plPL', 'Bzzzzzt!$B$BWitaj w matrycowym perforografie 3005 łamane na C, terminalu o poziomie zabezpieczeń chi.$B$BWykryto niebieską kartę perforowaną. Dostęp przyznany.\n01000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001', '', 0),
(4173, 'plPL', 'Bzzzzzt!$B$BWitaj w matrycowym perforografie 3005 łamane na D, terminalu o poziomie zabezpieczeń delta.$B$BWykryto czerwoną kartę perforowaną. Dostęp przyznany.\n01001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111', '', 0),
(4206, 'plPL', '', 'Świetnie! Bez twojej pomocy nigdy nie udałoby mi się odeprzeć tej fali troggów.', 0),
(4207, 'plPL', '', 'Słyszysz coś?', 0),
(4208, 'plPL', '', 'Coś tam usłyszałam.', 0),
(4209, 'plPL', '', 'Więcej troggów! Odpieraj je, a ja przygotuję materiały wybuchowe!', 0),
(4325, 'plPL', '', 'Ostatni ładunek założony. Odsuń się!', 0),
(4326, 'plPL', '', '10 sekund do wybuchu! Odsuń się!!!', 0),
(4327, 'plPL', '', '5 sekund do detonacji!!!!!', 0),
(4446, 'plPL', '', 'Wspaniale! Dzięki twojej pomocy mój lud ma szansę odbić nasze ukochane miasto. Trzykrotne hura na twoją cześć!', 0),
(5504, 'plPL', 'Może cię to zaszokuje, ale ostatnio interesy nie idą najlepiej...', '', 0),
(6177, 'plPL', 'Elektryczna sprawiedliwość!', '', 0),
(27926, 'plPL', 'Słyszysz coś?', '', 0),
(32326, 'plPL', 'UWAGA, ODPALAM!', 'UWAGA, ODPALAM!', 0);
